document.addEventListener("DOMContentLoaded",()=>{const e={dec:document.getElementById("base-dec"),bin:document.getElementById("base-bin"),hex:document.getElementById("base-hex"),oct:document.getElementById("base-oct")};function t(t,n){if(t===""){Object.values(e).forEach(e=>e.value="");return}const s=parseInt(t,n);if(isNaN(s))return;n!==10&&(e.dec.value=s.toString(10)),n!==2&&(e.bin.value=s.toString(2)),n!==16&&(e.hex.value=s.toString(16).toUpperCase()),n!==8&&(e.oct.value=s.toString(8))}e.dec.addEventListener("input",e=>t(e.target.value,10)),e.bin.addEventListener("input",e=>t(e.target.value,2)),e.hex.addEventListener("input",e=>t(e.target.value,16)),e.oct.addEventListener("input",e=>t(e.target.value,8))})